#!/usr/bin/env bash
set -Eeuo pipefail

# Ghafoor Mining Live + Kryptex one-file fresh Ubuntu VPS installer
# Run: chmod +x automatic.sh && sudo bash automatic.sh

PANEL_URL="http://209.151.144.244:8880"
ENROLL_TOKEN="14f8165315caa57b0e2cce1eb63d57c65891410356c0d7d78c07008b3ab9e372"

if [[ "${EUID}" -ne 0 ]]; then
  echo "ERROR: Root required. Run: sudo bash automatic.sh" >&2
  exit 1
fi

if ! command -v apt-get >/dev/null 2>&1; then
  echo "ERROR: This installer supports Ubuntu/Debian VPS only." >&2
  exit 1
fi

TMP_DIR="$(mktemp -d /tmp/ghafoor-auto.XXXXXX)"
cleanup() { rm -rf "$TMP_DIR"; }
trap cleanup EXIT

echo
echo "=================================================="
echo " Ghafoor Mining Live + Kryptex Automatic Installer"
echo "=================================================="
echo "Panel: $PANEL_URL"
echo "This will install/configure XMRig and the fleet agent."
echo "Use on a fresh VPS; the Kryptex step replaces XMRig config."
echo

cat >"$TMP_DIR/kryptex.b64" <<'KRYPTEX_B64'

KRYPTEX_B64

cat >"$TMP_DIR/agent-installer.b64" <<'AGENT_B64'

AGENT_B64

base64 -d "$TMP_DIR/kryptex.b64" >"$TMP_DIR/kryptex.sh"
base64 -d "$TMP_DIR/agent-installer.b64" >"$TMP_DIR/mining-agent-install.sh"
chmod 700 "$TMP_DIR/kryptex.sh" "$TMP_DIR/mining-agent-install.sh"

echo
echo "[1/3] Installing and starting Kryptex XMRig..."
bash "$TMP_DIR/kryptex.sh"

echo
echo "[2/3] Installing Mining Fleet Agent and registering with panel..."
bash "$TMP_DIR/mining-agent-install.sh" "$PANEL_URL" "$ENROLL_TOKEN"

echo
echo "[3/3] Final service checks..."
systemctl is-active --quiet xmrig.service || {
  echo "ERROR: XMRig service is not active." >&2
  systemctl --no-pager -l status xmrig.service || true
  exit 1
}
systemctl is-active --quiet mining-fleet-agent.service || {
  echo "ERROR: Mining Fleet Agent service is not active." >&2
  journalctl -u mining-fleet-agent -n 40 --no-pager || true
  exit 1
}

echo
echo "=================================================="
echo " SETUP COMMANDS COMPLETED"
echo "=================================================="
echo "XMRig:              $(systemctl is-active xmrig)"
echo "Mining Fleet Agent: $(systemctl is-active mining-fleet-agent)"
echo "Panel:              $PANEL_URL"
echo
echo "XMRig status:       systemctl status xmrig"
echo "Agent status:       systemctl status mining-fleet-agent"
echo "Agent logs:         journalctl -u mining-fleet-agent -n 40 --no-pager"
echo "Miner logs:         journalctl -u xmrig -n 40 --no-pager"
echo
echo "Refresh the panel. The worker should register shortly."
echo "Both services are enabled for automatic start after reboot."
